/**
 * Information about a single Lucide icon.
 */
export interface IconInfo {
  /** Human-readable name, e.g. "Circle User". */
  name: string;
  /** The icon component function. */
  icon: (...children: NodeChild[]) => Node;
  /** Search tags. */
  tags: string[];
  /** Categories the icon belongs to. */
  categories: string[];
}

